column3:
for i in pages.indices {
    let blanks = leading(pages[i])
    pages[i].removeFirst(machine.map { min($0, blanks) } ?? blanks)
    while let last = pages[i].last, isBlank(last) {
        pages[i].removeLast()
    }
}

column4:
while pages.count > 1, pages[pages.count - 1].isEmpty {
    pages.removeLast()
}
for i in pages.indices {
    let blanks = leading(pages[i])
    pages[i].removeFirst(machine.map { min($0, blanks) } ?? blanks)
    while let last = pages[i].last, isBlank(last) {
        pages[i].removeLast()
    }
}
return pages
